export type Post = {
  id: string
  title: string
  content: string
  createdAt: Date
}

export async function createPost(formData: FormData): Promise<{ success: boolean }> {
  const title = formData.get('title') as string
  const content = formData.get('content') as string

  if (!title || !content) {
    return { success: false }
  }

  const newPost: Post = {
    id: crypto.randomUUID(),
    title,
    content,
    createdAt: new Date(),
  }

  const posts = await getPostsFromStorage()
  posts.unshift(newPost)
  await savePostsToStorage(posts)

  revalidateTag('posts')

  return { success: true }
}

async function getPostsFromStorage(): Promise<Post[]> {
  const posts = await fetch('http://localhost:3000/api/posts', {
    cache: 'no-store',
  })
  if (!posts.ok) return []
  return posts.json()
}

async function savePostsToStorage(posts: Post[]): Promise<void> {
  await fetch('http://localhost:3000/api/posts', {
    method: 'POST',
    body: JSON.stringify(posts),
  })
}

export async function getPosts(): Promise<Post[]> {
  const res = await fetch('http://localhost:3000/api/posts', {
    next: { tags: ['posts'] },
  })
  if (!res.ok) return []
  return res.json()
}

